# Generated by the start-bridge codemod for infrastructure; re-run it instead of editing.
"""Validate and preserve the infrastructure staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.

``--profile production`` seals the cutover output after the workflow's config
rewrite: production worker, topLevelName and vars, same emitted fields as the
staging output. The default profile is the staging qualification.
"""
import importlib.util
import os
from pathlib import Path

WORKER = "tuturuuu-infrastructure-vite-staging"
PRODUCTION_WORKER = "tuturuuu-infrastructure"
PUBLIC_FILES = (
    "robots.txt",
)


def load(profile="staging"):
    if profile not in ("staging", "production"):
        raise ValueError("unknown infrastructure artifact profile")
    worker = PRODUCTION_WORKER if profile == "production" else WORKER
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("infrastructure_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": worker,
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": worker}
    module.RECEIPT = "infrastructure-native-artifact.json"
    if profile == "production":
        module.IDENTITY = {
            **module.IDENTITY,
            "vars": {
                "TUTURUUU_NOINDEX": "0",
                "NODE_ENV": "production",
                "TUTURUUU_REQUIRE_SECRETS": "1",
                "NEXT_PUBLIC_APP_URL": "https://infrastructure.tuturuuu.com",
                "NEXT_PUBLIC_WEB_APP_URL": "https://tuturuuu.com",
            },
        }
        module.NORMALIZED_DEFAULTS = {
            **module.NORMALIZED_DEFAULTS,
            "preview_urls": False,
            "upload_source_maps": False,
        }
        module.RECEIPT = "infrastructure-production-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    import sys
    profile = "staging"
    if len(sys.argv) > 1 and sys.argv[1] == "--profile":
        if len(sys.argv) < 3 or sys.argv[2] not in ("staging", "production"):
            raise SystemExit("only the staging and production artifact profiles are supported")
        profile = sys.argv[2]
        del sys.argv[1:3]
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "INFRASTRUCTURE_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["INFRASTRUCTURE_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load(profile).main()


if __name__ == "__main__":
    main()
